# Classic ELK pipeline
app -> Filebeat -> Logstash (parse/enrich) -> Elasticsearch (index) -> Kibana (UI)

# logstash.conf
input  { beats { port => 5044 } }
filter { grok { match => { "message" => "%{COMBINEDAPACHELOG}" } } }
output { elasticsearch { hosts => ["es:9200"] } }

# otel-collector config receiving all three signals over OTLP
receivers:
  otlp:
    protocols: {grpc: {endpoint: 0.0.0.0:4317}}
service:
  pipelines:
    traces:  {receivers: [otlp], exporters: [otlp/tempo]}
    metrics: {receivers: [otlp], exporters: [prometheusremotewrite]}
    logs:    {receivers: [otlp], exporters: [loki]}

# Three distinct series of the same metric name
http_requests_total{job="api", instance="10.0.0.5:8080", method="GET", code="200"}
http_requests_total{job="api", instance="10.0.0.5:8080", method="GET", code="500"}
http_requests_total{job="api", instance="10.0.0.6:8080", method="GET", code="200"}
# name + full label set = series identity

# Blackbox exporter probe run by Prometheus every 30s from outside the cluster
- job_name: synthetic-checkout
  metrics_path: /probe
  params: {module: [http_2xx]}
  static_configs: [{targets: ['https://shop.example.com/healthz']}]
  relabel_configs:
    - {source_labels: [__address__], target_label: __param_target}
    - {target_label: __address__, replacement: blackbox-exporter:9115}

# otel-collector-config.yaml
receivers:
  otlp: {protocols: {grpc: {}, http: {}}}
processors:
  batch: {}
  memory_limiter: {limit_mib: 512, check_interval: 1s}
exporters:
  otlp/tempo: {endpoint: tempo:4317, tls: {insecure: true}}
service:
  pipelines:
    traces: {receivers: [otlp], processors: [memory_limiter, batch], exporters: [otlp/tempo]}
